result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/enrich.test.mjs", "content": "import test from 'node:test';
import assert from 'node:assert/strict';
import { totalSpend } from './enrich.mjs';

function makeLookup() {
  let calls = 0;
  const lookupSpend = (id) =>
    new Promise((resolve) => {
      calls += 1;
      setTimeout(() => resolve(id * 10), 5);
    });
  return { lookupSpend, get callCount() { return calls; } };
}

test('sums concurrent lookups', async () => {
  const { lookupSpend } = makeLookup();
  const total = await totalSpend([1, 2, 3], lookupSpend);
  assert.equal(total, 60);
});

test('handles empty input', async () => {
  const { lookupSpend } = makeLookup();
  const total = await totalSpend([], lookupSpend);
  assert.equal(total, 0);
});

test('lookups stay concurrent (50 x 20ms finishes well under 500ms)', async () => {
  const ids = Array.from({ length: 50 }, (_, i) => i + 1);
  const { lookupSpend } = makeLookup();
  const start = performance.now();
  const total = await totalSpend(ids, lookupSpend);
  const elapsed = performance.now() - start;
  // Sum of 1..50 times 10
  assert.equal(total, (50 * 51 * 10) / 2);
  assert.ok(elapsed < 500, `expected <500ms for concurrent lookups, took ${elapsed.toFixed(1)}ms`);
});

test('rejects when a lookup rejects', async () => {
  const lookupSpend = async (id) => {
    if (id === 2) throw new Error('boom');
    return id * 10;
  };
  await assert.rejects(totalSpend([1, 2, 3], lookupSpend), /boom/);
});
"})
print(result)

